 static Stream Payload(){return Assembly.GetExecutingAssembly().GetManifestResourceStream("StringChat.Package.zip");}
 public static string Install(string root,string legacy,bool integrate,bool desktop,Action<int> progress){
  root=InstallSupport.Full(root);Directory.CreateDirectory(root);if((File.GetAttributes(root)&FileAttributes.ReparsePoint)!=0)throw new IOException("Escolha uma pasta sem redirecionamentos.");
  string stage=Path.Combine(root,".staging-"+Guid.NewGuid().ToString("N")),target=Path.Combine(root,InstallSupport.Version),backup=Path.Combine(root,".rollback-"+Guid.NewGuid().ToString("N"));bool committed=false,movedOld=false,installedNew=false;byte[] oldState=File.Exists(Path.Combine(root,"current.json"))?File.ReadAllBytes(Path.Combine(root,"current.json")):null;InstallSupport.IntegrationBackup integrations=null;var launchers=new Dictionary<string,byte[]>();foreach(string name in new[]{"StringChat.exe","StringChatMaintenance.exe"}){string path=Path.Combine(root,name);launchers[path]=File.Exists(path)?File.ReadAllBytes(path):null;}
  try{
   using(var stream=Payload())InstallSupport.Extract(stream,stage,value=>{if(progress!=null)progress(value*70/100);});InstallSupport.ValidatePackage(stage);InstallSupport.VerifyExecutable(stage);if(progress!=null)progress(78);
