   InstallSupport.RequireInside(root,target);Directory.Move(stage,target);installedNew=true;
   // A stable launcher keeps shortcuts and pinned links valid across future upgrades.
   File.Copy(Path.Combine(target,"StringChatMaintenance.exe"),Path.Combine(root,"StringChatMaintenance.exe"),true);File.Copy(Path.Combine(target,"StringChatMaintenance.exe"),Path.Combine(root,"StringChat.exe"),true);
   string currentFile=Path.Combine(root,"current.json"),nextFile=Path.Combine(root,".current-"+Guid.NewGuid().ToString("N")+".tmp");File.WriteAllText(nextFile,InstallSupport.Json.Serialize(new{product=InstallSupport.Product,version=InstallSupport.Version}));if(File.Exists(currentFile))File.Replace(nextFile,currentFile,null);else File.Move(nextFile,currentFile);
   if(integrate)InstallSupport.Register(root,desktop);committed=true;if(progress!=null)progress(92);
   var warnings=new List<string>();try{warnings.AddRange(InstallSupport.CleanupVersions(root,target));}catch{warnings.Add(root);}if(legacy!=root)try{warnings.AddRange(InstallSupport.CleanupVersions(legacy,target));if(Directory.Exists(legacy)&&(string.Equals(InstallSupport.Full(legacy),InstallSupport.Full(InstallSupport.LegacyRoot),StringComparison.OrdinalIgnoreCase)||InstallSupport.Inside(root,legacy))&&(File.GetAttributes(legacy)&FileAttributes.ReparsePoint)==0&&Directory.GetFileSystemEntries(legacy).Length==0)Directory.Delete(legacy,false);}catch{warnings.Add(legacy);}if(movedOld)try{InstallSupport.DeleteOwned(root,backup);}catch{warnings.Add(backup);}
   return warnings.Count==0?"Versão "+InstallSupport.Version+" instalada e verificada.\nAs versões anteriores instaladas foram removidas.\nSeu perfil e suas conversas foram mantidos.":"Versão "+InstallSupport.Version+" instalada. Seu perfil foi mantido.\nAlguns arquivos antigos estão em uso e serão removidos\nna próxima atualização; a versão nova já está pronta.";
  }catch{if(!committed){if(installedNew&&Directory.Exists(target))try{InstallSupport.DeleteOwned(root,target);}catch{}if(movedOld&&Directory.Exists(backup)&&!Directory.Exists(target))Directory.Move(backup,target);if(oldState!=null)File.WriteAllBytes(Path.Combine(root,"current.json"),oldState);else if(File.Exists(Path.Combine(root,"current.json")))File.Delete(Path.Combine(root,"current.json"));foreach(var file in launchers){if(file.Value==null){if(File.Exists(file.Key))File.Delete(file.Key);}else File.WriteAllBytes(file.Key,file.Value);}if(integrations!=null)integrations.Restore();}throw;}
  finally{if(Directory.Exists(stage))try{InstallSupport.DeleteOwned(root,stage);}catch{}}
 }
 [STAThread]static void Main(string[] args){
  if(args.Length==2&&args[0]=="--unpack"){try{using(var stream=Payload())InstallSupport.Extract(stream,Path.GetFullPath(args[1]),null);InstallSupport.ValidatePackage(Path.GetFullPath(args[1]));}catch{Environment.ExitCode=1;}return;}
